use std::fmt::Write;

use super::field_name;
use crate::{
    output::RawOutput,
    schema::{AstType, Schema, TypeId},
};

pub(super) fn native_types(schema: &Schema) -> RawOutput {
    let mut output = String::from(
        "// Generated by ast_tools. Do not edit.\n\nexport interface BaseNode {\n  type: string;\n  start: number;\n  end: number;\n}\n",
    );
    let mut nodes = Vec::new();
    for ty in &schema.types {
        match ty {
            AstType::Struct(ast) => {
                nodes.push(ast.name.as_str());
                writeln!(
                    output,
                    "\nexport interface {} extends BaseNode {{\n  type: {:?};",
                    ast.name, ast.name
                )
                .unwrap();
                for field in &ast.fields {
                    writeln!(
                        output,
                        "  {}: {};",
                        field_name(&field.name),
                        field_type(schema, field.type_id)
                    )
                    .unwrap();
                }
                output.push_str("}\n");
            }
            AstType::Enum(ast) => {
                let variants = ast
                    .variants
                    .iter()
                    .filter_map(|variant| variant.type_id)
                    .map(|id| schema.types[id].name())
                    .collect::<Vec<_>>();
                writeln!(
                    output,
                    "\nexport type {} = {};",
                    ast.name,
                    variants.join(" | ")
                )
                .unwrap();
            }
            _ => (),
        }
    }
    for enumeration in &schema.scalar_enums {
        if matches!(enumeration.name.as_str(), "Lang" | "SourceType") {
            continue;
        }
        let variants = enumeration
            .variants
            .iter()
            .map(|variant| format!("{:?}", variant.name))
            .collect::<Vec<_>>();
        writeln!(
            output,
            "\nexport type {} = {};",
            enumeration.name,
            variants.join(" | ")
        )
        .unwrap();
    }
    output.push_str("\nexport type Node =\n");
    for name in nodes {
        writeln!(output, "  | {name}").unwrap();
    }
    output.push_str(";\n");
    RawOutput {
        path: "npm/core-ffi2/src-js/protocol/native-types.d.ts".into(),
        content: output.into_bytes(),
    }
}

fn field_type(schema: &Schema, id: TypeId) -> String {
    match &schema.types[id] {
        AstType::Option(option) => format!("{} | null", field_type(schema, option.inner_type_id)),
        AstType::SubRange(range) => format!("Array<{}>", field_type(schema, range.inner_type_id)),
        AstType::Primitive(primitive) => match primitive.name {
            "AstUtf8" | "AstWtf8" => "string".into(),
            "bool" => "boolean".into(),
            "u8" | "i8" | "u16" | "i16" | "u32" | "i32" | "f64" => "number".into(),
            name => name.into(),
        },
        ty => ty.name().into(),
    }
}
